      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-plugin-namecards\",\n  \"version\": \"0.6.2\",\n  \"description\": \"插件名片：给插件换图标、中文名和说明，按文件夹/收藏整理，支持拖拽排序、列表/铺陈视图与启停开关；只改显示，不动插件本身。\",\n  \"icon\": \"icon.svg\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\",\n    \"./icon\": \"./icon.svg\",\n    \"./locale/en.json\": \"./locale/en.json\",\n    \"./locale/zh.json\": \"./locale/zh.json\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\"\n    }\n  },\n  \"files\": [\n    \"lib\",\n    \"assets\",\n    \"seed\",\n    \"locale\",\n    \"cordis.patch.yml\",\n    \"icon.svg\",\n    \"README.md\",\n    \"LICENSE\"\n  ],\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/3Tiga3/dsh-plugin-namecards.git\"\n  },\n  \"homepage\": \"https://github.com/3Tiga3/dsh-plugin-namecards#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/3Tiga3/dsh-plugin-namecards/issues\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"plugin-manager\",\n    \"name-cards\",\n    \"icons\",\n    \"chinese\"\n  ],\n  \"engines\": {\n    \"dsh\": \">=0.2.0-rc.1\"\n  },\n  \"author\": \"3Tiga3\"\n}\n"
