      "content": "/**\n * 插件名片 · 浏览器半边（v0.2）\n *\n * 页签：\n *  - 备注管理：按文件夹/收藏分组，组合包可折叠子行；右侧编辑图标/说明/备注\n *  - 插件管理：列表 / 铺陈两种视图，文件夹、收藏、拖拽排序、启用开关\n * 详情页：保留「名片」区块\n */\nwindow.__ModuleLoader__.load({\n  id: \"dsh-plugin-namecards\",\n  factory: (require) => {\n    const react = require(\"react\")\n    const { useCallback, useEffect, useMemo, useRef, useState } = react\n    const { jsx, jsxs } = require(\"react/jsx-runtime\")\n\n    const name = \"dsh-plugin-namecards\"\n    const inject = [\"slots\"]\n    const BASE = \"/dsh-plugin-namecards\"\n    const MAX_DESC = 300\n    const MAX_NOTE = 60\n    const COLLATOR = new Intl.Collator(\"zh-Hans-CN\", { numeric: true, sensitivity: \"base\" })\n\n    /* ---------------- 工具 ---------------- */\n\n    function iconUrl(token) {\n      if (typeof token !== \"string\") return undefined\n      if (token.indexOf(\"builtin:\") === 0) return BASE + \"/icon/builtin/\" + token.slice(8) + \".svg\"\n      if (token.indexOf(\"file:\") === 0) return BASE + \"/icon/file/\" + token.slice(5)\n      return undefined\n    }\n\n    function rowKey(bundleName, rowId) { return bundleName + \"#\" + rowId }\n\n    function resolveText(value) {\n      if (typeof value === \"string\") return value\n      if (value === null || typeof value !== \"object\") return undefined\n      const lang = String((document.documentElement && document.documentElement.lang) || navigator.language || \"zh\").toLowerCase()\n      if (typeof value[lang] === \"string\") return value[lang]\n      if (lang.indexOf(\"zh\") === 0 && typeof value.zh === \"string\") return value.zh\n      if (typeof value.en === \"string\") return value.en\n      const values = Object.keys(value).map((k) => value[k]).filter((v) => typeof v === \"string\")\n      return values.length > 0 ? values[0] : undefined\n    }\n\n    function isHan(text) { return /[\\u3400-\\u9fff]/.test(String(text || \"\")) }\n\n    async function apiGet(path) {\n      const response = await fetch(BASE + path, { headers: { Accept: \"application/json\" }, credentials: \"same-origin\" })\n      if (!response.ok) throw new Error(\"HTTP \" + response.status)\n      return response.json()\n    }\n\n    async function apiPost(path, body) {\n      const response = await fetch(BASE + path, {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\", Accept: \"application/json\" },\n        credentials: \"same-origin\",\n        body: JSON.stringify(body)\n      })\n      const data = await response.json().catch(() => ({}))\n      if (!response.ok || data.ok === false) throw new Error(data.error || (\"HTTP \" + response.status))\n      return data\n    }\n\n    /* @dsh-plugin-namecards-css-start */\n    const CSS_TEXT = \".dpc-root{display:flex;flex-direction:column;gap:14px;color:var(--dsw-alias-label-primary,#e9ecf2);font-size:13px;line-height:20px;max-width:100%}\\n.dpc-bar{display:flex;flex-wrap:wrap;align-items:center;gap:10px}\\n.dpc-spacer{flex:1}\\n.dpc-hint{color:var(--dsw-alias-label-tertiary,#8e96a5);font-size:12px;line-height:18px}\\n.dpc-btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;height:30px;padding:0 12px;border-radius:8px;border:1px solid var(--dsw-alias-border-l3,#2a2f3a);background:transparent;color:inherit;font:inherit;cursor:pointer;text-decoration:none;box-sizing:border-box}\\n.dpc-btn:hover{background:var(--dsw-alias-interactive-bg-hover,#1f242e)}\\n.dpc-btn[disabled]{opacity:.5;cursor:default}\\n.dpc-btn--primary{background:var(--dsw-alias-state-business-primary,#5b8cff);border-color:transparent;color:#0b1220;font-weight:600}\\n.dpc-btn--danger{color:#f27373}\\n.dpc-input,.dpc-textarea{box-sizing:border-box;width:100%;border:1px solid var(--dsw-alias-border-l3,#2a2f3a);border-radius:9px;background:var(--dsw-alias-bg-l1,#14171d);color:inherit;font:inherit;padding:8px 10px;resize:vertical}\\n.dpc-input:focus,.dpc-textarea:focus{outline:2px solid var(--dsw-alias-state-business-primary,#5b8cff);outline-offset:-1px